Una cocina tiene recetas que necesitan otras recetas ya hechas, y se quiere un orden de preparación.

function ordenCocina(recetas) {
  const faltan = new Map(recetas.map((r) => [r.nombre, r.necesita.length]));
  const usan = new Map(recetas.map((r) => [r.nombre, []]));
  for (const r of recetas) for (const d of r.necesita) usan.get(d).push(r.nombre);
  const fila = recetas.filter((r) => r.necesita.length === 0).map((r) => r.nombre);
  const orden = [];
  for (let i = 0; i < fila.length; i++) {
    orden.push(fila[i]);
    for (const u of usan.get(fila[i])) {
      faltan.set(u, faltan.get(u) - 1);
      if (faltan.get(u) === 0) fila.push(u);
    }
  }
  return orden.length === recetas.length ? orden : null;
}
